use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,io::Read,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/mixed-sdk";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn main(){let r=Path::new(R);let out=r.join("diagnostic-v2-source");assert!(!out.exists());let m=read(format!("{Z}/docs/benchmarks/2026-10-27-clean-fft-adoption/artifacts/production-source-manifest.json"));
    let mut files=m["source_files_sha256"].as_object().unwrap().keys().cloned().collect::<Vec<_>>();files.extend(["crates/zopro-core/src/msm/mixed_g1.rs".into(),"crates/zopro-core/src/msm_geometry.rs".into()]);
    for f in &files {let p=out.join(f);fs::create_dir_all(p.parent().unwrap()).unwrap();fs::copy(r.join("diagnostic-source").join(f),p).unwrap();}
    let mut inverse=BTreeMap::new();for f in ["crates/zopro-core/src/msm_affine.rs","crates/zopro-core/src/msm_affine/borrowed_pending.rs"]{let p=out.join(f);let original=fs::read_to_string(&p).unwrap();let needle="                *current = Affine::<C>::IDENTITY;\n";assert_eq!(original.matches(needle).count(),1);let replace=format!("                self.geometry.cancelled();\n{needle}");let s=original.replacen(needle,&replace,1);assert_eq!(s.replacen(&replace,needle,1),original);fs::write(p,s).unwrap();inverse.insert(f,vec![(needle,replace)]);}
    let p=out.join("crates/zopro-core/src/msm_geometry.rs");let original=fs::read_to_string(&p).unwrap();let needle="    pub(crate) fn pushed(&mut self)";let added="    pub(crate) fn cancelled(&mut self) {if self.active {add(&mut self.local,\"cancelled_updates\",1);}}\n";assert_eq!(original.matches(needle).count(),1);fs::write(&p,original.replacen(needle,&format!("{added}{needle}"),1)).unwrap();fs::copy(&p,r.join("observer-v2.rs")).unwrap();
    let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r.join("build-pins.json"))).unwrap();for f in &files{let p=out.join(f);pins.insert(p.display().to_string(),hash(&p));}
    for f in ["diagnostic-extend.rs","diagnostic-extend","observer-v2.rs"]{let p=r.join(f);pins.insert(p.display().to_string(),hash(p));}
    save(r.join("diagnostic-v2-pins.json"),&json!(pins));let mut plan=read(r.join("build-diagnostic.json"));plan["source_pins"]=json!(r.join("diagnostic-v2-pins.json"));plan["steps"][0]["argv"][3]=json!(out.join("Cargo.toml"));plan["steps"][1]["artifacts"]=json!(r.join("native-diagnostic-v2/libraries/stdout.log"));save(r.join("build-diagnostic-v2.json"),&plan);
    save(r.join("diagnostic-v2-audit.json"),&json!({"old_diagnostic_sources_untouched":true,"new_source_files":files.len(),"cancel_hooks_inverse_edits":inverse,"main_arithmetic_sha256":hash(r.join("source/crates/zopro-core/src/msm/mixed_g1.rs")),"diagnostic_arithmetic_sha256":hash(out.join("crates/zopro-core/src/msm/mixed_g1.rs")),"change":"Count inverse-point cancellations as logical digit updates; no arithmetic changes"}));
}
